const CELL = 32, cells = new Map();
const key = (cx, cy) => `${cx},${cy}`;
const cellOf = (cx, cy) => cells.get(key(cx, cy)) ?? cells.set(key(cx, cy), []).get(key(cx, cy));

function insert(e) { cellOf(Math.floor(e.x / CELL), Math.floor(e.y / CELL)).push(e); }
function near(x, y, r) {
  const out = [];
  for (let cy = ((y - r) / CELL | 0); cy <= ((y + r) / CELL | 0); cy++)
    for (let cx = ((x - r) / CELL | 0); cx <= ((x + r) / CELL | 0); cx++)
      for (const e of cells.get(key(cx, cy)) ?? [])
        if ((e.x - x) ** 2 + (e.y - y) ** 2 <= r * r) out.push(e);
  return out;
}

